//! 코어가 플랫폼에 요구하는 것.
//!
//! 스캔 상태기계는 '언제 무엇을 할지'를 정하고, 그것을 '어떻게 하는지'는 모른다.
//! 여기가 그 경계다.
//!
//! 경계를 두는 이유는 플랫폼마다 실행 방법이 근본적으로 다르기 때문이다.
//! 데스크톱은 OS에 키 이벤트를 주입하지만, 안드로이드는 다른 앱으로의 키 주입을
//! 아예 막아 두어서 접근성 서비스로 포커스를 옮기는 방식밖에 없다. `>`가 데스크톱에서는
//! `Tab`이고 안드로이드에서는 `focusSearch(FOCUS_FORWARD)`가 된다. 그래도 '다음 요소로
//! 옮긴다'는 결정 자체는 같으므로, 그 결정을 내리는 코드는 한 벌이면 된다.

use crate::action::Action;
use crate::cue::Cue;
use crate::profile::{Profile, UndoMapping};
use crate::scan::Snapshot;

/// 실행 실패. 사용자에게 그대로 보여줄 수 있는 문구를 담는다.
pub struct HostError {
    pub message: String,
    /// 권한 문제로 보이는 경우. 화면에서 해결 방법을 함께 안내한다.
    pub needs_permission: bool,
}

/// 화면으로 내보낼 것.
pub enum Notice {
    /// 지금 커서가 어디에 있고 무엇이 보여야 하는지.
    State(Box<Snapshot>),
    Error {
        message: String,
        needs_permission: bool,
    },
    /// 간격이 바뀐 이유. 이유를 알 수 없는 변화는 통제감을 무너뜨린다(원칙 2).
    Interval {
        from_ms: u64,
        to_ms: u64,
        reason: String,
    },
    /// 앱별 칸이 갈렸다.
    Preset { message: String },
}

pub trait Host: Send + Sync + 'static {
    /// 대상 앱에 동작을 보낸다.
    fn inject(&self, action: Action) -> Result<(), HostError>;

    /// 되돌리기. 대상 앱이 그 단축키를 지원할 때만 실제로 되돌아간다(PRD F6).
    fn undo(&self, mapping: UndoMapping) -> Result<(), HostError>;

    /// 설정 화면을 연다. 키 주입이 아니라 우리 앱 내부 동작이다.
    fn open_settings(&self) -> Result<(), HostError>;

    /// 칸 수가 달라졌으니 화면을 거기에 맞춘다.
    ///
    /// 화면과 실제 칸이 어긋나면 사용자는 보이지 않는 칸을 누르게 된다.
    fn fit_cells(&self, extras: usize);

    /// 두 감각 중 소리 쪽(원칙 4).
    fn cue(&self, cue: Cue);

    fn set_sound(&self, enabled: bool);

    fn publish(&self, notice: Notice);

    /// 조정된 간격을 파일에 적는다.
    ///
    /// 조정될 때마다 적는다. 종료 시에만 저장하면 강제 종료에서 사용자가
    /// 익숙해진 속도를 잃는다.
    fn save_profile(&self, profile: &Profile);
}

        // 우리 자신은 누르지 않는다. 컨트롤러의 칸을 눌러 버리면 사용자가
        // 고르려던 것 대신 우리 UI가 반응하고, 되돌릴 방법이 없다.
        if (isOurs(focused)) {
            Log.w(TAG, "선택 실패: 우리 앱의 요소라 누르지 않음")
            return false
        }

        // 사람이 하듯 그 자리를 실제로 두드린다.
        //
        // `ACTION_CLICK`을 먼저 썼다가 실기에서 크게 헤맸다. 웹 콘텐츠에서는
        // 그것이 **참을 돌려주고도 링크를 열지 않는다.** 로그에는 '선택 됨'이
        // 찍히는데 화면은 그대로여서, 되는 줄 알고 넘어가기 쉽다.
        if (tap(focused)) return true

        // 두드릴 수 없을 때만 semantic 액션으로 물러선다. 좌표가 없거나 화면
        // 밖에 있는 요소가 여기 온다.
        var node: AccessibilityNodeInfo? = focused
        var depth = 0
        while (node != null) {
            if (isOurs(node)) break
            if (node.isClickable && node.performAction(AccessibilityNodeInfo.ACTION_CLICK)) {
                Log.i(TAG, "선택 됨(액션) ${describe(node)} (조상 $depth 단계 위)")
                return true
            }
            node = node.parent
            depth += 1
        }

        Log.w(TAG, "선택 실패: 누를 수 없음 ${describe(focused)}")
        return false
    }

    /**
     * 요소의 한가운데를 실제로 두드린다.
     *
     * 화면 밖으로 걸친 요소는 보이는 부분의 한가운데를 잡는다. 요소의 기하학적
     * 중심이 화면 밖이면 두드려도 아무 데도 닿지 않는다.
     */
    private fun tap(node: AccessibilityNodeInfo): Boolean {
        val bounds = android.graphics.Rect()
        node.getBoundsInScreen(bounds)

        val screen =
            android.graphics.Rect(
                0,
                0,
                resources.displayMetrics.widthPixels,
                resources.displayMetrics.heightPixels,
            )
        if (!bounds.intersect(screen)) {
            Log.w(TAG, "두드리기 건너뜀: 화면 밖 ${describe(node)}")
            return false
        }

        val point = tapPoint(bounds) ?: run {
            Log.w(TAG, "두드리기 건너뜀: 컨트롤러에 완전히 가림 ${describe(node)}")
            return false
        }

        val path =
            android.graphics.Path().apply {
                moveTo(point.x, point.y)
            }
        val gesture =
            android.accessibilityservice.GestureDescription.Builder()
                .addStroke(
                    android.accessibilityservice.GestureDescription.StrokeDescription(
                        path,
                        0L,
                        TAP_MS,
                    ),
                )
                .build()

        val sent = dispatchGesture(gesture, null, null)
